-- Hyprland config (Lua). Wiki: https://wiki.hypr.land/Configuring/Start/
-- Original autogenerated example is saved as hyprland.lua.bak

-------------
-- MONITOR --
-------------

-- Every screen: best resolution, placed automatically.
-- scale = 1 means no zoom ("auto" picked 1.5 on this laptop, which made apps too big).
-- Try 1.25 if 1 feels too small.
hl.monitor({ output = "", mode = "preferred", position = "auto", scale = 1 })


--------------
-- PROGRAMS --
--------------

local terminal    = "kitty"
local fileManager = "pcmanfm"
-- wmenu-run: dmenu for Wayland. A bar across the top; type, Enter runs it.
-- -i ignore case, -f font, -N/-n normal bg/text, -S/-s selected bg/text,
-- -M/-m prompt bg/text. Colors match waybar.
local menu        = "wmenu-run -i -f 'JetBrainsMono Nerd Font 11'"
    .. " -N 1e1e2e -n dddddd -S 33ccff -s 1e1e2e -M 33ccff -m 1e1e2e"


---------------
-- AUTOSTART --
---------------

-- Runs once when Hyprland starts.
hl.on("hyprland.start", function()
    -- Wallpaper: whatever was last picked in waypaper; on a fresh machine with no
    -- waypaper config yet, the one in the dotfiles, scaled to fill the screen.
    local wp = io.open(os.getenv("HOME") .. "/.config/waypaper/config.ini")
    if wp then
        wp:close()
        hl.exec_cmd("waypaper --restore")
    else
        hl.exec_cmd("swaybg -m fill -i ~/.config/hypr/wallpaper.jpg")
    end
    hl.exec_cmd("waybar")                                -- top bar
    hl.exec_cmd("mako")                                  -- notifications
    -- Auto lock / screen off / suspend, on laptops only (they have a BAT0 or
    -- BAT1). The PC stays on until locked or suspended by hand.
    local bat = io.open("/sys/class/power_supply/BAT0") or io.open("/sys/class/power_supply/BAT1")
    if bat then
        bat:close()
        hl.exec_cmd("hypridle")
    end
    hl.exec_cmd("nm-applet")                             -- wifi icon in the bar tray
    hl.exec_cmd("systemctl --user start hyprpolkitagent") -- password prompts for GUI apps
    -- Dark mode for GTK4 apps and anything asking the desktop portal (Firefox).
    -- Set here so it's in the dotfiles; GTK 3 apps read ~/.config/gtk-3.0/settings.ini.
    hl.exec_cmd("gsettings set org.gnome.desktop.interface color-scheme prefer-dark")
end)


-----------------
-- ENVIRONMENT --
-----------------

hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")

-- NVIDIA (the PC's RTX 2060): point VA-API and GLX at NVIDIA's libraries, per
-- the Hyprland wiki. Only when the NVIDIA driver is loaded, so the laptop's
-- Intel GPU keeps its own drivers.
local nv = io.open("/proc/driver/nvidia/version")
if nv then
    nv:close()
    hl.env("LIBVA_DRIVER_NAME", "nvidia")
    hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
end


-------------------
-- LOOK AND FEEL --
-------------------

hl.config({
    general = {
        gaps_in     = 4,    -- space between windows
        gaps_out    = 8,    -- space between windows and screen edge
        border_size = 2,
        col = {
            active_border   = "rgba(33ccffee)",  -- focused window border
            inactive_border = "rgba(595959aa)",  -- other windows
        },
        layout = "dwindle", -- i3-like tiling: each new window splits the focused one
    },

    decoration = {
        rounding = 6,
        shadow   = { enabled = false },
        blur     = { enabled = false },
    },

    animations = {
        enabled = true,
    },

    dwindle = {
        preserve_split = true,  -- a split stays horizontal/vertical once set
    },

    misc = {
        force_default_wallpaper = 0,    -- no anime mascot wallpaper
        disable_hyprland_logo   = true, -- plain background instead
    },
})

-- Animations: speed is in tenths of a second, so 3 = 0.3s.
-- (Hyprland's built-in default is 10 = a full second, which feels sluggish.)
-- "snappy" starts fast and eases into place. Every animation inherits "global".
hl.curve("snappy", { type = "bezier", points = { {0.23, 1}, {0.32, 1} } })
hl.animation({ leaf = "global", enabled = true, speed = 3, bezier = "snappy" })


-----------
-- INPUT --
-----------

hl.config({
    input = {
        kb_layout    = "us",
        repeat_delay = 300, -- ms to hold a key before it starts repeating (default 600)
        repeat_rate  = 40,  -- repeats per second while held (default 25)
        follow_mouse = 1,   -- focus follows the mouse pointer
        sensitivity  = 0,   -- mouse speed, -1.0 to 1.0
        touchpad = {
            natural_scroll = true,  -- scroll like a phone
        },
    },
})

-- Swipe 3 fingers left/right on the touchpad to change workspace.
hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })


-----------------
-- KEYBINDINGS --
-----------------

local mainMod = "SUPER"  -- the Windows key

-- Apps
hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + D",      hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + E",      hl.dsp.exec_cmd(fileManager))

-- Windows
hl.bind(mainMod .. " + SHIFT + Q",     hl.dsp.window.close())
hl.bind(mainMod .. " + F",             hl.dsp.window.fullscreen({ action = "toggle" }))
hl.bind(mainMod .. " + SHIFT + space", hl.dsp.window.float({ action = "toggle" }))

-- Splits, like i3: choose where the NEXT window opens, then open it.
hl.bind(mainMod .. " + B", hl.dsp.layout("preselect r"))  -- next window to the right (side by side)
hl.bind(mainMod .. " + V", hl.dsp.layout("preselect d"))  -- next window below (stacked)

-- Session
hl.bind(mainMod .. " + SHIFT + E", hl.dsp.exit())
hl.bind(mainMod .. " + Escape",    hl.dsp.exec_cmd("hyprlock"))

-- Focus / move windows: arrows or vim keys (h j k l), like i3
local directions = {
    left = "left", right = "right", up = "up", down = "down",
    h = "left", l = "right", k = "up", j = "down",
}
for key, dir in pairs(directions) do
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ direction = dir }))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ direction = dir }))
end

-- Workspaces: Super+1..0 to switch, Super+Shift+1..0 to send window there
for i = 1, 10 do
    local key = i % 10  -- workspace 10 is the 0 key
    hl.bind(mainMod .. " + " .. key,         hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- Mouse: hold Super and drag with left button = move, right button = resize
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Screenshots go to ~/Pictures and are also copied to the clipboard
-- grim writes the image to stdout (-), tee saves it to a file AND passes it on to wl-copy
local save = " - | tee ~/Pictures/$(date +%F_%H-%M-%S).png | wl-copy"
hl.bind("Print",         hl.dsp.exec_cmd("grim" .. save))                    -- whole screen
hl.bind("SHIFT + Print", hl.dsp.exec_cmd("grim -g \"$(slurp)\"" .. save))    -- drag to select area

-- Volume / brightness keys (work even on the lock screen, repeat when held)
local media = { locked = true, repeating = true }
hl.bind("XF86AudioRaiseVolume",  hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), media)
hl.bind("XF86AudioLowerVolume",  hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      media)
hl.bind("XF86AudioMute",         hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true })
hl.bind("XF86AudioMicMute",      hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true })
hl.bind("XF86MonBrightnessUp",   hl.dsp.exec_cmd("brightnessctl set 5%+"),                          media)
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl set 5%-"),                          media)

-- Media player keys (needs playerctl)
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


------------------
-- WINDOW RULES --
------------------

-- Don't let apps maximize themselves; the tiling layout decides sizes.
hl.window_rule({
    name  = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})

-- Steam games (class steam_app_<id>) open truly fullscreen: no gaps, border or bar.
hl.window_rule({
    name  = "steam-games-fullscreen",
    match = { class = "^steam_app_.*" },
    fullscreen = true,
})

-- Fixes drag-and-drop glitches in some X11 (XWayland) apps.
hl.window_rule({
    name  = "fix-xwayland-drags",
    match = { class = "^$", title = "^$", xwayland = true, float = true, fullscreen = false, pin = false },
    no_focus = true,
})
